/** Services shown on the site. Set `published: false` on a service to hide it without deleting it. */
export const publishedServiceDetails: ServiceDetail[] = serviceDetails.filter((service) => service.published !== false);
export const allServiceItems: (ServiceGroup | ServiceDetail)[] = [...serviceCatalog, ...publishedServiceDetails];
export function findService(slug: string) { return allServiceItems.find((service) => service.slug === slug); }
export function servicesInCategory(slug: string) { return publishedServiceDetails.filter((service) => service.categorySlug === slug); }
export function categoryFor(service: ServiceDetail) { return serviceCatalog.find((group) => group.slug === service.categorySlug); }
export function isServiceDetail(service: ServiceGroup | ServiceDetail): service is ServiceDetail { return "categorySlug" in service; }

