/** Search-result title for a service page, without repeating "in Jamshedpur". */
export function serviceSeoTitle(service: ServiceGroup | ServiceDetail) {
  if (isServiceDetail(service) && service.seoTitle) return service.seoTitle;
  if (SEO_TITLES[service.slug]) return SEO_TITLES[service.slug];
  return /jamshedpur/i.test(service.title) ? service.title : `${service.title} in Jamshedpur`;
}

function trimAtWord(text: string, max: number) {
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  return `${cut.slice(0, cut.lastIndexOf(" ")).replace(/[,;:.\s]+$/, "")}…`;
}

export function serviceSeoDescription(service: ServiceGroup | ServiceDetail) {
  if (isServiceDetail(service) && service.seoDescription) return service.seoDescription;
  const suffix = " NISE COMPORT, Kharangajhar, Telco, Jamshedpur.";
  const base = service.description.trim();
  return base.length + suffix.length <= 160 ? base + suffix : trimAtWord(base, 160);
}

/** Where "Start request" goes for a service: PAN and printing have their own step flows. */
export function requestHrefFor(slug: string) {
  if (slug === "pan-card") return "/pan/request";
  if (slug === "printing-scanning") return "/print";
  if (serviceCatalog.some((group) => group.slug === slug)) return `/request?category=${encodeURIComponent(slug)}`;
  return `/request?service=${encodeURIComponent(slug)}`;
}

/** Short, card-friendly name: drops the trailing location and "Assistance"/"Help" filler. */
export function shortServiceName(title: string) {
  return title.replace(/\s+(in|near)\s+(Jamshedpur|Telco)(,.*)?$/i, "").replace(/\s+\((BC Point)\)$/i, "").replace(/\s+(Assistance|Help)$/i, "").trim();
}
